/** The boat engine of a release (`options.version`, else the registry's), an instance of that release's class. */
export function createNativeBoatPhysics(registry: PhysicsRegistry, options: NativeEngineOptions = {}): NativeBoatPhysics {
    const version = resolveRegistryRelease(registry, options.version);
    const Engine: VersionedNativeBoatPhysicsClass = NATIVE_BOAT_ENGINES[version];
    return new Engine(registry, { binding: options.binding, requireParity: options.requireParity });
}

