/** The ridden mob engine of a release (`options.version`, else the registry's), an instance of that release's class. */
export function createNativeRiddenMobPhysics(registry: PhysicsRegistry, options: NativeEngineOptions = {}): NativeRiddenMobPhysics {
    const version = resolveRegistryRelease(registry, options.version);
    const Engine: VersionedNativeRiddenMobPhysicsClass = NATIVE_RIDDEN_MOB_ENGINES[version];
    return new Engine(registry, { binding: options.binding, requireParity: options.requireParity });
}
